// Brute force SDF blur
// By PauloFalcao
//
// SDF blur using fibonacci points in a sphere
// Change #define iterations 55 at line 39
// 
// Since I learned how to do raymarching, I've wanted to do SDFs blur
// I have some posts on Pouet about it in 2011
//   - https://www.pouet.net/topic.php?post=367378
//   - https://www.pouet.net/topic.php?post=367436
// But the truth is that I've never managed to make something interesting
// Is it even possible?
// This why is one of the possible "brute force" ones.
// Sampling the SDF in a sphere in a Fibonacci point distribution.
// It's brute force, but you can create some interesting things with it.
// Try changing iterations it to a low value, and you'll get some crystal-like forms! :)
//
// I also have a node for this in my MaterialMaker raymarching lib
// https://github.com/paulofalcao/MaterialMakerRayMarching
//

//https://iquilezles.org/articles/distfunctions
float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}


//Test Object
float sdf_a(vec3 p){
  float b=sdBox(p,vec3(1.3,1.3,1.3));
  float s=length(p)-1.5;

  return max(b,-s);
}


#define iterations 55
// blur obj is sdf_a
// b is the blur amount
// f is just the bounding object size
//   so it only blurs when close to the object
float blursdf3d(/*obj vec3->float*/in vec3 p,in float b,float f){
    /*obj vec3->float = sdf_a*/
	float a=0.0;
	float d=sdf_a(p);
	if (d<b*f){
        /*iterations*/
		for(int i=0;i<iterations;i++){
	        float y=1.0-2.0*(float(i)/float(iterations));
	        float r=sqrt(1.0-y*y);
	        float t=2.39996322973*float(i);
			a+=sdf_a(p+vec3(cos(t)*r,y,sin(t)*r)*b);
		}
	} else{
		return d;
	}
	return a/float(iterations);
}


//Object Color
vec3 tex3d_a(vec3 p){
    return vec3(1.0,0.0,0.0);
}

//Floor
float sdf_b(vec3 p){
    return max(p.y+2.0,length(p)-8.0);
}

//Floor color
vec3 tex3d_b(vec3 p){
    p*=2.0;
	vec2 w=max(abs(dFdx(p.xz)),abs(dFdy(p.xz)))+1e-5;
	if (max(w.x,w.y)>0.5) {
		return vec3(mod(floor(p.x)+floor(p.z),2.0));
	}
	vec2 i=((1.-abs(2.*fract((p.xz+.5*w)/2.)-1.))-(1.-abs(2.*fract((p.xz-.5*w)/2.)-1.)))/w;
	return vec3(.5-.5*i.x*i.y);
}


//Rotation
vec2 rot(vec2 p,float f){
    float s=sin(f);float c=cos(f);
    return p*mat2(c,-s,s,c);
}

//Combine the 2 SDFs
vec2 sdf(vec3 p) {

    vec3 p_obja=p;
    //Rotate the object sdfa
    p_obja.yz=rot(p_obja.yz,sin(iTime*0.5)*2.0);
    p_obja.xz=rot(p_obja.xz,sin(iTime*0.2)*0.5);
    p_obja.xy=rot(p_obja.xy,sin(iTime*0.03)*2.0);

    float sdfa=blursdf3d(p_obja,sin(iTime)*0.1+0.15,0.1);
	float sdfb=sdf_b(p);
	if (sdfa<sdfb) {
	  return vec2(sdfa,0.0);
	} else {
	  return vec2(sdfb,1.0);
	}
}


//definition
vec3 raymarch(vec2 uv,vec3 camera,float cameraZoom,vec3 lookAt,
    float cameraDistance,vec3 sun, float ambLightIntensity,
    float lightPow,float lightSpecular,float reflection);

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    //setup uv
    vec2 uv=fragCoord/iResolution.xy-0.5;
    uv.x*=iResolution.x/iResolution.y;

    //rendering parameters
    vec3 camera=vec3(sin(sin(iTime*0.3)*0.5+0.5)*4.0,2.0,cos(cos(iTime*0.2)*0.5+0.5)*4.0);
    float cameraZoom=1.5;
    vec3 lookAt=vec3(0.0,0.0,0.0);
    float cameraDistance=1.1;
    vec3 sun=vec3(0.0,2.0,2.5);
    float ambOcclusion=1.0;
    float shadowIntensity=1.0;
    float ambLightIntensity=0.25;
    float lightPow=128.0;
    float lightSpecular=0.7;
    float reflection=0.2;
    vec3 col = raymarch(uv,camera,cameraZoom,lookAt,cameraDistance,sun,
        ambLightIntensity,lightPow,lightSpecular,reflection);

    fragColor = vec4(pow(col,vec3(1.0/2.2)),1.0);
}


//************************* Rendering framework ****************************************

vec3 normal(vec3 p){  
  const vec2 e=vec2(0.001,-0.001);
  float x=sdf(p+e.xyy).x;
  float y=sdf(p+e.yxy).x;
  float z=sdf(p+e.yyx).x;
  return normalize(vec3(x-y-z,-x+y-z,-x-y+z)+sdf(p+e.xxx).x);
}

void march(inout float d,out vec3 p,out vec2 dS,in vec3 ro,in vec3 rd){
    for (int i=0; i < 100; i++) {
    	p = ro + rd*d;
        dS = sdf(p);
        d += dS.x;
        if (d > 20.0 || abs(dS.x) < 0.0001) break;
    }
}


vec3 hdri(vec3 p,float v) {
	return pow(texture(iChannel0, p).xyz, vec3(2.2))
    + pow(texture(iChannel0, p).xxx, vec3(16.0)) * v;
}

vec3 raymarch(
        vec2 uv,
        vec3 camera,
        float cameraZoom,
        vec3 lookAt,
        float cameraDistance,
        vec3 sun,
        float ambLightIntensity,
        float lightPow,
        float lightSpecular,
        float reflection) {
	vec3 cam=camera*cameraZoom;
	vec3 ray=normalize(lookAt-cam);
	vec3 cX=normalize(cross(vec3(0.0,1.0,0.0),ray));
	vec3 cY=normalize(cross(ray,cX));
	vec3 rd = normalize(ray*cameraDistance+cX*uv.x+cY*uv.y);
	vec3 ro = cam;

	float d=0.;
	vec3 p=vec3(0.);
	vec2 dS=vec2(0.);
	march(d,p,dS,ro,rd);

    vec3 color=vec3(0.);
	vec3 objColor=(dS.y<0.5)?tex3d_a(p):tex3d_b(p);
	vec3 light=normalize(sun);
	if (d<20.0) {
	    vec3 n=normal(p);
		float l=clamp(dot(-light,-n),0.,1.0);
		vec3 ref=normalize(reflect(rd,-n));
		float r=clamp(dot(ref,light),0.,1.0);
		color=max(ambLightIntensity,l)*objColor+pow(r,lightPow)*lightSpecular;
		//reflection
        d=0.01;
		march(d,p,dS,p,ref);
		vec3 objColorRef=vec3(0.);
		if (d<20.0) {
			objColorRef=(dS.y<0.5)?tex3d_a(p):tex3d_b(p);
			n=normal(p);
			l=clamp(dot(-light,-n),0.,1.);
			objColorRef=max(l,ambLightIntensity)*objColorRef;
		} else {
			objColorRef=hdri(ref.zyx,1.0);
		}
		color=mix(color,objColorRef,reflection);
	} else {
		color=hdri(rd.zyx,0.0);
	}
	return color;
}
